import{Utils}from"../utils.min.js?v=1.0.0";import Feature_Base_Component from"./base-component.min.js?v=1.0.0";let Product_Based_Shipping={extends:Feature_Base_Component,template:"#shipflex-product-based-shipping-feature-component",data(){return{calculation_value:"",calculation_mode:"percentage",calculate_basis:"fixed_amount",advanced_calculation_tiers:[],...shipflex_admin?.features?.["product-based-shipping"],...this.featureData}},updated(){},computed:{show_calculation_value(){return"fixed_amount"==this.calculate_basis||"fixed_amount"!=this.calculate_basis&&"tiered_rates"!=this.calculation_mode},calculation_metrics(){return shipflex_admin.calculation_metrics}},methods:{unit_label(e){return this.$root.get_unit_label(this.calculate_basis,e)},add_shipping_cost_range(){this.add_collection("advanced_calculation_tiers",{id:Utils.generate_uuid()})}}};export default Product_Based_Shipping;